CREATE DATABASE IF NOT EXISTS maganlal_chikki_bi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE maganlal_chikki_bi;
CREATE TABLE categories(category_id INT PRIMARY KEY,category_name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE suppliers(supplier_id INT PRIMARY KEY,supplier_name VARCHAR(160) NOT NULL,phone VARCHAR(40),lead_time_days INT NOT NULL DEFAULT 7,INDEX idx_supplier_name(supplier_name));
CREATE TABLE products(product_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,product_code VARCHAR(40) NOT NULL UNIQUE,product_name VARCHAR(160) NOT NULL,category_id INT NOT NULL,category VARCHAR(80) NOT NULL,net_weight DECIMAL(10,2) NOT NULL,unit VARCHAR(12) NOT NULL,selling_price DECIMAL(12,2) NOT NULL CHECK(selling_price>0),purchase_price DECIMAL(12,2) NOT NULL CHECK(purchase_price>0),current_stock DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(current_stock>=0),minimum_stock DECIMAL(12,2) NOT NULL DEFAULT 0,reorder_level DECIMAL(12,2) NOT NULL DEFAULT 0,barcode VARCHAR(80) UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(category_id),INDEX idx_product_category(category_id),INDEX idx_product_stock(current_stock,reorder_level));
CREATE TABLE product_suppliers(product_supplier_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,supplier_id INT NOT NULL,normalized_name VARCHAR(160) NOT NULL,canonical_weight DECIMAL(16,6) NOT NULL,canonical_unit VARCHAR(20) NOT NULL,CONSTRAINT uq_product_supplier_identity UNIQUE(supplier_id,normalized_name,canonical_weight,canonical_unit),CONSTRAINT uq_product_supplier_pair UNIQUE(product_id,supplier_id),FOREIGN KEY(product_id) REFERENCES products(product_id) ON DELETE CASCADE,FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id) ON DELETE CASCADE,INDEX idx_product_supplier_product(product_id),INDEX idx_product_supplier_supplier(supplier_id));
CREATE TABLE sales(sale_id BIGINT PRIMARY KEY,sale_code VARCHAR(40) NOT NULL UNIQUE,sale_date DATE NOT NULL,total DECIMAL(14,2) NOT NULL CHECK(total>=0),status VARCHAR(20) NOT NULL DEFAULT 'completed',INDEX idx_sales_date(sale_date),INDEX idx_sales_status(status));
CREATE TABLE sale_items(sale_item_id BIGINT AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT NOT NULL,product_id INT NOT NULL,quantity DECIMAL(12,2) NOT NULL CHECK(quantity>0),unit_price DECIMAL(12,2) NOT NULL CHECK(unit_price>0),unit_cost DECIMAL(12,2) NOT NULL CHECK(unit_cost>=0),FOREIGN KEY(sale_id) REFERENCES sales(sale_id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(product_id),INDEX idx_sale_item_product(product_id));
CREATE TABLE purchases(purchase_id BIGINT PRIMARY KEY,supplier_id INT NOT NULL,purchase_date DATE NOT NULL,total DECIMAL(14,2) NOT NULL CHECK(total>=0),status VARCHAR(20) NOT NULL DEFAULT 'paid',FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id),INDEX idx_purchase_date(purchase_date));
CREATE TABLE purchase_items(purchase_item_id BIGINT AUTO_INCREMENT PRIMARY KEY,purchase_id BIGINT NOT NULL,product_id INT NOT NULL,quantity DECIMAL(12,2) NOT NULL CHECK(quantity>0),unit_cost DECIMAL(12,2) NOT NULL CHECK(unit_cost>=0),FOREIGN KEY(purchase_id) REFERENCES purchases(purchase_id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE inventory(product_id INT PRIMARY KEY,current_stock DECIMAL(12,2) NOT NULL CHECK(current_stock>=0),minimum_stock DECIMAL(12,2) NOT NULL,reorder_level DECIMAL(12,2) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE inventory_movements(movement_id BIGINT PRIMARY KEY,product_id INT NOT NULL,movement_date DATE NOT NULL,movement_type VARCHAR(30) NOT NULL,quantity DECIMAL(12,2) NOT NULL,reference VARCHAR(80),FOREIGN KEY(product_id) REFERENCES products(product_id),INDEX idx_movement_product_date(product_id,movement_date));
CREATE TABLE expenses(expense_id BIGINT PRIMARY KEY,expense_date DATE NOT NULL,category VARCHAR(80) NOT NULL,description VARCHAR(255),amount DECIMAL(12,2) NOT NULL CHECK(amount>=0),INDEX idx_expense_date(expense_date));
CREATE TABLE payments(payment_id BIGINT PRIMARY KEY,payment_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL CHECK(amount>=0),payment_type VARCHAR(30) NOT NULL,reference VARCHAR(80),related_type VARCHAR(20),related_id BIGINT,status VARCHAR(20) NOT NULL,INDEX idx_payment_date_status(payment_date,status));
CREATE TABLE returns(return_id BIGINT PRIMARY KEY,return_date DATE NOT NULL,sale_id BIGINT NOT NULL,reason VARCHAR(255),total_value DECIMAL(12,2) NOT NULL CHECK(total_value>=0),FOREIGN KEY(sale_id) REFERENCES sales(sale_id),INDEX idx_return_date(return_date));
CREATE TABLE return_items(return_item_id BIGINT PRIMARY KEY,return_id BIGINT NOT NULL,product_id INT NOT NULL,quantity DECIMAL(12,2) NOT NULL CHECK(quantity>0),unit_value DECIMAL(12,2) NOT NULL CHECK(unit_value>=0),FOREIGN KEY(return_id) REFERENCES returns(return_id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE calendar_dates(calendar_date DATE PRIMARY KEY,year SMALLINT NOT NULL,quarter TINYINT NOT NULL,month TINYINT NOT NULL,week_of_year TINYINT NOT NULL,day_of_week TINYINT NOT NULL,day_name VARCHAR(12) NOT NULL);
CREATE TABLE forecast_results(forecast_id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NULL,generated_at DATETIME NOT NULL,period_start DATE NOT NULL,horizon_days INT NOT NULL,forecast_quantity DECIMAL(12,2) NOT NULL,method VARCHAR(80) NOT NULL,FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE business_insights(insight_id BIGINT AUTO_INCREMENT PRIMARY KEY,generated_at DATETIME NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,severity VARCHAR(20) NOT NULL,related_metric VARCHAR(80) NOT NULL,supporting_value DECIMAL(14,2) NOT NULL,INDEX idx_insight_generated(generated_at));
CREATE TABLE reorder_recommendations(recommendation_id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,generated_at DATETIME NOT NULL,days_of_stock DECIMAL(10,2) NULL,suggested_quantity DECIMAL(12,2) NOT NULL,lead_time_days INT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(product_id),INDEX idx_reorder_product(product_id));
CREATE TABLE etl_logs(etl_id BIGINT AUTO_INCREMENT PRIMARY KEY,started_at DATETIME NOT NULL,finished_at DATETIME NULL,status VARCHAR(20) NOT NULL,records_processed INT NOT NULL DEFAULT 0,warnings INT NOT NULL DEFAULT 0,errors INT NOT NULL DEFAULT 0,details JSON,INDEX idx_etl_started(started_at));
